import{_ as l,l as d,o as t,c as s,v as i,p,x as r,d as o,i as c,S as B,b as a}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"kdb+ 与 q","description":"","frontmatter":{"title":"kdb+ 与 q","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/kdb-plus.md","filePath":"quant/kdb-plus.md","lastUpdated":1789023840000}'),h={name:"quant/kdb-plus.md"};function q(D,e,u,k,b,E){const n=d("Mermaid");return t(),s("div",null,[e[1]||(e[1]=i('<h1 id="kdb-与-q" tabindex="-1">kdb+ 与 q <a class="header-anchor" href="#kdb-与-q" aria-label="Permalink to &quot;kdb+ 与 q&quot;">​</a></h1><div class="epigraph"><p>把当天的逐笔放进内存列存，把历史按日期分区落盘，中间用一条只追加的日志把两者接住——kdb+ 的行情栈不是「又一个 SQL 库」，而是为金融时序的追加与向量扫描而长出来的进程拓扑。</p><footer>—— 据 Kx Systems 对 kdb+ 与 q 的技术说明；行情库常见的 tickerplant / RDB / HDB 分工</footer></div><p>微观结构研究与生产行情库面对同一物理事实：数据按时间追加、查询却按列扫描（某几只证券的某几个字段、某一时间窗）。行式库把同一时刻的所有字段捆在一起，对「只要成交价与量」的扫描极不友好；通用数据湖又把延迟与模式演进丢给上层。kdb+ 用列存、枚举符号、内存映射与一种 APL 风格的向量语言 q，把「当天热数据」和「按日分区的历史」拆成可独立伸缩的进程。<a href="/quant/clickhouse-finance-ts">ClickHouse 金融时序</a> 与 <a href="/quant/dolphindb">DolphinDB</a> 解决的是相近问题，但进程模型与语言不同。本篇写 kdb+ 作为数据架构：表如何躺在内存与盘上、TP/RDB/HDB 如何衔接、以及 q 的向量语义如何既加速又制造错误。它不是一份可执行的生产部署手册，也不涉及未授权接入实时行情口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Tick 的写入是追加：每条成交、每条报价只发生一次，几乎不更新（除了晚到与更正）。读取却是分析型的：某日某标的的全部成交价、按时间对齐的买卖一档、一段窗口上的聚合。若存储按行，聚合必须跳过无关字段；若没有按日期与符号的分区，一次「昨天这只股票」会扫到整个库。kdb+ 把表看成命名列的集合，列是同质向量；符号列被枚举成整数，比较与分组变成对小整数的向量运算。问题是如何在全日不中断写入的同时，让分析查询走满向量化，并且在日终把内存表变成可内存映射的历史分区。</p><p>第二个问题是语言。SQL 的声明式对连接与过滤很稳，但对「把这列与其滞后做一次向量减、再按符号分组取最后一条」写起来冗长，且优化器不一定选列式计划。q 把表当作翻转的列字典，查询是向量表达式。表达力换来的是可维护性与隐式广播错误——架构讨论必须把语言风险算进去。</p><h3 id="列存、枚举与按日分区" tabindex="-1">列存、枚举与按日分区 <a class="header-anchor" href="#列存、枚举与按日分区" aria-label="Permalink to &quot;列存、枚举与按日分区&quot;">​</a></h3><p>一张成交表至少有时间、符号、价、量。列存意味着「只要价」只读一列；过滤符号时先走枚举后的整数向量。历史库按日期分区：每个日期一个目录，目录内按列分文件。查询某一天只打开那天的文件，操作系统的页缓存可以按列预读。跨日查询由 q 把各分区的结果拼接，这要求各日模式一致——加列必须是可演进的，而不能默默错位。</p><p><span class="marginnote">kdb+ 的「内存数据库」指的是 RDB 与当前热分区可以全部放进 RAM，不是所有历史都必须常驻。HDB 靠 mmap：只用到的列页被装入。把三年逐笔强行全部 <code>select</code> 进内存，仍然会把机器打满。容量规划按「并发查询触及的列×时间窗」来，而不是按库的名义体积。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准行情拓扑分三截。<strong>Tickerplant（TP）</strong> 从上游馈送收消息，做最小解析与时间戳，写入只追加日志，再发布给订阅者。它不负责复杂计算，以便崩溃后能从日志重放。<strong>RDB</strong> 订阅当天数据，表留在内存，供盘中查询与监控。<strong>HDB</strong> 存历史分区；日终把 RDB 的表写到新的日期目录，清空内存表，准备下一个交易日。更正与晚到消息要么写入单独的更正通道，要么在次日以补充文件存在分区里——与 <a href="/quant/late-data-recon">迟到数据对账</a> 是同一类问题，只是实现落在列文件而不是对象存储。</p><p>查询规划应显式：先按日期缩小分区，再按符号，再取列。q 里写反顺序，解释器仍可能先物化一张大表。对高频用户，常用的聚合应预计算成 bar 表，而不是每次从 tick 现场 <code>select</code>。预计算是研究与生产的分界：研究可以扫原始成交；生产仪表盘应读 bar。两者的时间戳定义必须一致，否则 <a href="/quant/pit-alignment">时点对齐</a> 会在两套表之间裂开。</p><h3 id="q-的向量语义与表" tabindex="-1">q 的向量语义与表 <a class="header-anchor" href="#q-的向量语义与表" aria-label="Permalink to &quot;q 的向量语义与表&quot;">​</a></h3><p>q 的原子是列表。标量运算自动沿列表走；表是特殊字典。<code>update</code>、<code>delete</code>、<code>select</code> 看起来像 SQL，但求值顺序、左连接与窗口函数的语义是 q 自己的。典型加速来自「先过滤再计算」与「避免逐行循环」：能写成列运算的不要写成 <code>each</code>。反面是隐式对齐：两条不等长的列表相加会报错，两个按不同符号排序的表做运算却可能静默错位。架构规范应要求：任何跨表运算前，键与排序不变量被断言。</p><p>与 <a href="/quant/apache-arrow">Apache Arrow 零拷贝</a> 的交界：kdb+ 有自己的内存布局，并不等于 Arrow RecordBatch。把结果交给 Python 研究栈时，通常会发生一次拷贝或一次 IPC。若研究侧以 Arrow 为交换格式，应把导出做成显式批次，而不是在回调里逐行吐 pandas。零拷贝只有在双方同意同一布局时才成立。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制上，TP/RDB/HDB 是把「追加写」和「分析读」拆到不同的失败域。TP 的职责是不丢消息与保持次序；RDB 的职责是低延迟的当日全量；HDB 的职责是可并行的历史扫描。日志是两者之间的契约：RDB 挂了可以从日志重建当天，HDB 不参与盘中写入，避免把分析查询的锁带进馈送路径。这与 <a href="/quant/event-driven-backtest">事件驱动回测</a> 的事件队列是同一因果观念：时钟由到达的记录推进，而不是由一个全局 SQL 事务推进。</p><p>q 作为实现语言，把「对一整列做同一件事」变成默认路径，于是清洗、加栏、简单特征可以在库内完成，减少数据搬出。这既是优点也是边界：复杂的机器学习不应塞进 q 脚本里「顺便」跑，而应把特征表按日分区导出。库内计算的审计比外部作业更难：没有自然的作业图，只有脚本与 cron。生产上应把 q 脚本当成代码，纳入版本与测试，而不是当成一次性查询。</p><h3 id="日终切换与查询隔离" tabindex="-1">日终切换与查询隔离 <a class="header-anchor" href="#日终切换与查询隔离" aria-label="Permalink to &quot;日终切换与查询隔离&quot;">​</a></h3><p>日终写分区时，HDB 需要看到完整的一天。常见做法是先写到临时目录，再原子改名；查询进程重载根路径。切换窗口里，若有人查询「今天」，应明确是 RDB 还是尚未可见的新分区。隔离做不好会出现双读或空洞。多站点复制时，次序以 TP 日志为准，而不是以某个 RDB 的内存快照为准。这些是架构不变量，与 q 的语法糖无关。</p><p><span class="marginnote">把研究用的临时 <code>select</code> 直接嵌进生产订阅回调，是把交互式语言的习惯带进馈送路径。回调里只做 O(1) 或严格限额的向量运算；重查询走专门的查询进程。否则一次全表扫描会拖住整个 tickerplant 的下游。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>kdb+ 不是通用事务库：改历史某一格，代价是重写列文件或追加更正。它也不是分布式 SQL 的替代品——集群靠进程拓扑与共享存储协议，而不是隐藏分片的查询引擎。许可与运维成本高，团队必须会 q；把 q 当成「短 SQL」来写，会既慢又难读。Windows 与 Linux 部署的路径、内存锁定与 NUMA 都影响延迟，不能假设笔记本上的脚本等于机房里的 RDB。</p><p>不要用 HDB 当消息总线。不要在没有日期分区的单文件里堆多年 tick。不要假设 <code>select</code> 的结果顺序等于馈送顺序——若需要事件次序，必须保留序号列。中国市场的午休、夜盘与竞价段是分区日历问题，见相关制度条目；kdb+ 不会自动知道哪一段不该连成连续时间。</p><p><span class="marginnote">架构比较应看写入模型与查询模型，而不是基准测试海报上的单次聚合毫秒数。kdb+ 赢在追加型金融时序与向量语言的贴合；若工作负载是多表事务或临时宽表探索，别的引擎可能更合适。</span></p>',25)),(t(),p(B,null,{default:r(()=>[c(n,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20LR%0A%20%20Feed%5B%22%E4%B8%8A%E6%B8%B8%E9%A6%88%E9%80%81%22%5D%20--%3E%20TP%5B%22Tickerplant%22%5D%0A%20%20TP%20--%3E%20Log%5B%22%E5%8F%AA%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%22%5D%0A%20%20TP%20--%3E%20RDB%5B%22%E5%BD%93%E6%97%A5%E5%86%85%E5%AD%98%20RDB%22%5D%0A%20%20Log%20--%3E%20RDB%0A%20%20RDB%20--%3E%20EOD%5B%22%E6%97%A5%E7%BB%88%E5%86%99%E5%88%86%E5%8C%BA%22%5D%0A%20%20EOD%20--%3E%20HDB%5B%22%E6%8C%89%E6%97%A5%20HDB%22%5D%0A%20%20RDB%20--%3E%20Q1%5B%22%E7%9B%98%E4%B8%AD%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20HDB%20--%3E%20Q2%5B%22%E5%8E%86%E5%8F%B2%E6%89%AB%E6%8F%8F%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[o("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"kdb+ 用列存、枚举符号与按日分区，把当天内存表与历史 mmap 表拆成不同进程。"),a("li",null,"典型拓扑是 tickerplant、RDB、HDB，中间靠只追加日志重放。"),a("li",null,"q 把表当向量，加速来自列运算；隐式对齐与脚本化生产是主要风险。"),a("li",null,"与 Arrow、ClickHouse、DolphinDB 比较时应对齐写入与查询模型，而不是单次基准。"),a("li",null,"日终切换、更正通道与查询隔离是正确性条件，不是运维细节。"),a("li",null,"出处：Kx Systems kdb+ / q 文档与白皮书；金融行情库的 TP/RDB/HDB 是该生态的标准进程分工。")],-1))])}const f=l(h,[["render",q]]);export{m as __pageData,f as default};
